import { useState } from "react";
import Layout from "../layout/Layout";
import api from "../services/api";
import {
  TextField,
  Button,
  Typography,
  Box,
  Card,
  CardContent,
  Stack
} from "@mui/material";
import { useNavigate } from "react-router-dom";

export default function AddBook() {
  const [title, setTitle] = useState("");
  const [author, setAuthor] = useState("");
  const [isbn, setIsbn] = useState("");
  const [category, setCategory] = useState("");
  const navigate = useNavigate();

  const handleSubmit = async (e) => {
    e.preventDefault();

    try {
      await api.post("/books", { title, author, isbn, category });
      navigate("/books");
    } catch {
      alert("Failed to add book");
    }
  };

  return (
    <Layout>
      <Box
        sx={{
          display: "flex",
          justifyContent: "center",
          mt: { xs: 2, sm: 4 }
        }}
      >
        <Card
          sx={{
            width: "100%",
            maxWidth: 500,
            p: 2,
            borderRadius: 3,
            boxShadow: "0 10px 40px rgba(0,0,0,0.12), 0 0 40px rgba(59, 130, 246, 0.08)",
            transition: "all 0.3s cubic-bezier(0.4, 0, 0.2, 1)",
            "&:hover": {
              transform: "translateY(-4px)",
              boxShadow: "0 15px 50px rgba(0,0,0,0.15), 0 0 50px rgba(59, 130, 246, 0.12)"
            }
          }}
        >
          <CardContent sx={{ p: 3 }}>
            <Typography
              variant="h5"
              gutterBottom
              sx={{ fontWeight: 700, fontSize: { xs: "1.5rem", sm: "1.75rem" }, mb: 3 }}
            >
              Add New Book
            </Typography>

            <Typography variant="body2" color="text.secondary" mb={3}>
              Fill in the details below to add a new book to the library.
            </Typography>

            <form onSubmit={handleSubmit}>
              <Stack spacing={3}>
                <TextField
                  label="Book Title"
                  fullWidth
                  required
                  size="small"
                  value={title}
                  onChange={(e) => setTitle(e.target.value)}
                  sx={{
                    "& .MuiOutlinedInput-root": {
                      borderRadius: 2,
                      transition: "all 0.3s ease"
                    }
                  }}
                />

                <TextField
                  label="Author"
                  fullWidth
                  required
                  size="small"
                  value={author}
                  onChange={(e) => setAuthor(e.target.value)}
                  sx={{
                    "& .MuiOutlinedInput-root": {
                      borderRadius: 2,
                      transition: "all 0.3s ease"
                    }
                  }}
                />

                <TextField
                  label="ISBN"
                  fullWidth
                  required
                  size="small"
                  value={isbn}
                  onChange={(e) => setIsbn(e.target.value)}
                  sx={{
                    "& .MuiOutlinedInput-root": {
                      borderRadius: 2,
                      transition: "all 0.3s ease"
                    }
                  }}
                />

                <TextField
                  label="Category"
                  fullWidth
                  size="small"
                  value={category}
                  onChange={(e) => setCategory(e.target.value)}
                  sx={{
                    "& .MuiOutlinedInput-root": {
                      borderRadius: 2,
                      transition: "all 0.3s ease"
                    }
                  }}
                />

                <Button
                  type="submit"
                  variant="contained"
                  size="large"
                  fullWidth
                  sx={{
                    borderRadius: 2.5,
                    textTransform: "none",
                    fontWeight: 600,
                    mt: 2,
                    py: 1.5,
                    background: "linear-gradient(90deg, #2563EB, #1D4ED8)",
                    transition: "all 0.3s cubic-bezier(0.4, 0, 0.2, 1)",
                    "&:hover": {
                      transform: "scale(1.02)",
                      boxShadow: "0 12px 32px rgba(37, 99, 235, 0.4)",
                      background: "linear-gradient(90deg, #1D4ED8, #1E40AF)"
                    },
                    "&:active": {
                      transform: "scale(0.98)"
                    }
                  }}
                >
                  Add Book
                </Button>
              </Stack>
            </form>
          </CardContent>
        </Card>
      </Box>
    </Layout>
  );
}
